// Unit 6 of Mu'allim-ul-Quran: the present tense verb (fil-e-haal), book pages 213 onward.
// The book gives Arabic only; the Urdu meanings below were added, so check them with your teacher.

const pairs = (rows) => ({ type: "pairs", rtl: true, rows });
const heading = (text) => ({ type: "heading", text, rtl: true });
const sub = (text) => ({ type: "subheading", text, rtl: true });
const rule = (text, title = "قاعدہ") => ({ type: "callout", variant: "tip", title, text, rtl: true });
const note = (text, title = "نوٹ") => ({ type: "callout", variant: "note", title, text, rtl: true });
const L = (text) =>
  text
    .split("\n")
    .map((s) => s.trim())
    .filter(Boolean)
    .map((s) => {
      const i = s.indexOf("=");
      return [s.slice(0, i).trim(), s.slice(i + 1).trim()];
    });
const P = (text) => pairs(L(text));

export const unit6Lessons = [];
const add = (title, summary, theory) => unit6Lessons.push({ rtl: true, title, summary, theory });


